SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @R varchar(20)='$(RunToken)',@M int=TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion')),@Free bigint;IF '$(DemoId)'<>'STL-008' OR '$(TargetDatabase)'<>N'SQLPERF_LAB_STL008_'+@R THROW 51000,'FAIL_CONTRACT: STL-008-Zielkennung ist ungueltig.',1;IF '$(HighImpactConfirmed)'<>'1' OR '$(DisposableEnvironmentConfirmed)'<>'1' OR '$(RecoveryPlanConfirmed)'<>'1' BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_HIGH_IMPACT_CONFIRMATION_REQUIRED';RETURN;END;IF @M NOT BETWEEN 15 AND 17 BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_VERSION';RETURN;END;IF HAS_PERMS_BY_NAME(NULL,NULL,'CREATE ANY DATABASE')<>1 BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_PERMISSION';RETURN;END;SELECT @Free=MIN(v.available_bytes) FROM sys.master_files f CROSS APPLY sys.dm_os_volume_stats(f.database_id,f.file_id)v WHERE f.database_id=DB_ID(N'master');IF @Free<2147483648 BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_RESOURCE_PROFILE';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
